export type IconProps = Omit<React.ComponentProps<"svg">, "ref"> & {
  size?: number | string;
  weight?: IconWeight;
  mirrored?: boolean;
  /** accepted for compatibility; Phosphor icons are filled shapes */
  strokeWidth?: number | string;
};
export type IconComponent = React.ComponentType<IconProps> & { displayName?: string };

function icon(Ph: PhosphorIcon, name: string, weight: IconWeight): IconComponent {
  const I = ({ strokeWidth: _s, weight: w, ...props }: IconProps) => {
    void _s;
    return <Ph weight={w ?? weight} {...props} />;
  };
  I.displayName = name;
  return I;
}

