/** The real WhatsApp mark (Simple Icons) — used wherever the action opens WhatsApp. */
export const WhatsApp: IconComponent = Object.assign(
  ({ strokeWidth: _s, weight: _w, mirrored: _m, size, ...props }: IconProps) => {
    void _s;
    void _w;
    void _m;
    return <BrandIcon width={size ?? "1em"} height={size ?? "1em"} {...props} name="whatsapp" />;
  },
  { displayName: "WhatsApp" },
);
